$kinds = @{
  'Catalogs' = 'Справочник.'
  'Documents' = 'Документ.'
  'InformationRegisters' = 'РегистрСведений.'
}
$hits = New-Object System.Collections.Generic.List[string]
foreach ($kind in $kinds.Keys) {
  $dir = Join-Path 'd:\II\HTTP Demo BSP' $kind
  Get-ChildItem -Path $dir -Filter '*.xml' -File | ForEach-Object {
    $head = Get-Content -Path $_.FullName -TotalCount 12 -Encoding UTF8
    $text = $head -join "`n"
    $name = [regex]::Match($text, '<Name>([^<]*)</Name>').Groups[1].Value
    if (-not $name) { $name = $_.BaseName }
    $syn = [regex]::Match($text, '<v8:content>([^<]*)</v8:content>').Groups[1].Value
    $full = $kinds[$kind] + $name
    $blob = ($full + ' ' + $syn).ToLower().Replace('ё','е')
    if ($blob.Contains('цен')) {
      $hits.Add("$full`t$syn")
    }
  }
}
$sorted = $hits | Sort-Object
Write-Output ("count=" + $sorted.Count)
$i = 0
foreach ($line in $sorted) {
  if ($line.StartsWith('РегистрСведений._ДемоЦеныНоменклатуры')) {
    Write-Output ("index=" + $i + " " + $line)
  }
  $i++
}
Write-Output '--- sample ---'
$sorted | Select-Object -First 15

$prefix = @{
  'Catalogs' = 'Справочник.'
  'Documents' = 'Документ.'
  'InformationRegisters' = 'РегистрСведений.'
}
$hits = New-Object System.Collections.Generic.List[object]
foreach ($kind in $prefix.Keys) {
  $dir = Join-Path 'd:\II\HTTP Demo BSP' $kind
  Get-ChildItem -Path $dir -Filter '*.xml' -File | ForEach-Object {
    $text = [System.IO.File]::ReadAllText($_.FullName)
    $name = [regex]::Match($text, '<Name>([^<]*)</Name>').Groups[1].Value
    $syn = [regex]::Match($text, '<Synonym>[\s\S]*?<v8:content>([^<]*)</v8:content>').Groups[1].Value
    $full = $prefix[$kind] + $name
    $blob = ($full + ' ' + $syn).ToLower().Replace([char]0x0451, [char]0x0435)
    if ($blob.Contains('цен')) {
      $hits.Add([pscustomobject]@{ Full = $full; Syn = $syn; Kind = $kind })
    }
  }
}
$sorted = $hits | Sort-Object Full
$idx = 0
$found = -1
foreach ($h in $sorted) {
  if ($h.Full -eq 'РегистрСведений._ДемоЦеныНоменклатуры') { $found = $idx }
  $idx++
}
$docs = @($sorted | Where-Object { $_.Kind -eq 'Documents' }).Count
$cats = @($sorted | Where-Object { $_.Kind -eq 'Catalogs' }).Count
$regs = @($sorted | Where-Object { $_.Kind -eq 'InformationRegisters' }).Count
Write-Output "total=$($sorted.Count) documents=$docs catalogs=$cats registers=$regs index=$found"
Write-Output '--- before register ---'
$sorted | Select-Object -First $found | ForEach-Object { $_.Full + ' | ' + $_.Syn }

$prefix = @{
  'Catalogs' = 'Справочник.'
  'Documents' = 'Документ.'
  'InformationRegisters' = 'РегистрСведений.'
}
foreach ($needle in @('цена','цен')) {
  $n = 0
  $sample = New-Object System.Collections.Generic.List[string]
  foreach ($kind in $prefix.Keys) {
    $dir = Join-Path 'd:\II\HTTP Demo BSP' $kind
    Get-ChildItem -Path $dir -Filter '*.xml' -File | ForEach-Object {
      $text = [System.IO.File]::ReadAllText($_.FullName)
      $name = [regex]::Match($text, '<Name>([^<]*)</Name>').Groups[1].Value
      $syn = [regex]::Match($text, '<Synonym>[\s\S]*?<v8:content>([^<]*)</v8:content>').Groups[1].Value
      $full = $prefix[$kind] + $name
      $blob = ($full + ' ' + $syn).ToLower().Replace([char]0x0451, [char]0x0435)
      if ($blob.Contains($needle)) {
        $n++
        if ($sample.Count -lt 8) { $sample.Add($full + ' | ' + $syn) }
      }
    }
  }
  Write-Output "NEEDLE=$needle count=$n"
  $sample | ForEach-Object { Write-Output $_ }
}

