import {
  Callout,
  H1,
  H2,
  Pill,
  Row,
  Stack,
  Stat,
  Table,
  Text,
  useCanvasState,
  useHostTheme,
} from "cursor/canvas";

type Bucket = "decide" | "accept" | "plan";
type Filter = "all" | Bucket;

const FINDINGS: {
  bucket: Bucket;
  topic: string;
  tz: string;
  docs: string;
  resolution: string;
}[] = [
  {
    bucket: "decide",
    topic: "Поиск по слову «цена»",
    tz: "Сценарий 1: слово «цена» приводит к регистру цен номенклатуры.",
    docs: "Поиск остаётся подстрокой, как у справочников. «цена» не входит ни в «Цены», ни в _ДемоЦеныНоменклатуры. По выгрузке конфигурации такой запрос находит только Справочник.СценарииОбменовДанными. Запрос «цен» находит регистр цен первым из восьми совпадений, внутри предела 20. registers.http уже шлёт q=цен, план учит find_types брать основу слова.",
    resolution:
      "Принять спецификацию. Сценарий ТЗ — речь менеджера, в GET /types уходит основа «цен». Общий НайтиТипы не получает морфологию: им же ищутся справочники и документы, а их поведение ТЗ оставляет прежним.",
  },
  {
    bucket: "accept",
    topic: "История: «все» и порядок",
    tz: "Сценарий 4: все цены товара по периодам. Каркас инструмента обещает все записи.",
    docs: "Не больше 100 записей, hasMore, порядок от новых к старым. Параметра limit нет ни в схеме инструмента, ни в registers.http.",
    resolution:
      "Принять предел и порядок. Для одного товара демо-цены помещаются в 100. Слово «все» читать как записи по ключу измерений. Полная выгрузка меняла бы уже объявленную схему инструмента и заливала чат срезом без отбора.",
  },
  {
    bucket: "accept",
    topic: "Реквизиты при записи",
    tz: "Записать значение. Реквизиты входят в описание. Сценарии пишут цену и читают подразделение — это ресурсы.",
    docs: "Реквизитов в теле нет. При замене ресурсы меняются, реквизиты прежней записи сохраняются. У новой записи они пустые. В каркасе у write_register_record нет такого аргумента.",
    resolution:
      "Принять. Иначе замена значения сотрёт, например, табельный номер, которого клиент не передавал.",
  },
  {
    bucket: "accept",
    topic: "Полный ключ и все ресурсы",
    tz: "Запись на тот же период и ключ заменяет прежнее значение. Состав тела ТЗ не задаёт.",
    docs: "В dimensions — все измерения, в resources — все ресурсы. Пропуск или лишнее имя — 400 invalid_data до записи.",
    resolution:
      "Принять. Частичный ключ был бы другой записью. Пропущенный ресурс при замене стал бы пустым: у курсов это нулевая кратность.",
  },
  {
    bucket: "accept",
    topic: "Дата среза",
    tz: "Таблица показывает date. Сценарий — цена сейчас и месяц назад.",
    docs: "Без date срез на текущий момент сеанса. Дата без времени — конец этого дня, 23:59:59. Момент с временем берётся как есть. Будущая цена за текущую не выдаётся.",
    resolution:
      "Принять. Образец в таблице не делает дату обязательной. Конец дня нужен, чтобы «курс на сегодня» включал записи этого дня: у регистра цен периодичность — секунда.",
  },
  {
    bucket: "accept",
    topic: "Непериодический регистр",
    tz: "Поддерживаются независимые регистры сведений. Про регистр без периода ТЗ молчит.",
    docs: "Описание строится. Срез, история и запись отвечают 422 unsupported_operation. Контрольный пример — РегистрСведений._ДемоОтветственныеЛица.",
    resolution:
      "Принять. Операции ТЗ завязаны на дату и период. Регистр остаётся в описании, отказ объясняет, почему срез к нему неприменим.",
  },
  {
    bucket: "accept",
    topic: "Общие реквизиты",
    tz: "Описание строится по метаданным: новый ресурс появляется в описании без правки сервиса.",
    docs: "Общие реквизиты регистра спецификация не описывает.",
    resolution:
      "Принять для этой базы. Разделитель ОбластьДанныхОсновныеДанные на регистры действует, но сервис объектов разделители и так скрывает и берёт общие реквизиты только у справочников и документов. Прочие общие реквизиты в демо-регистры не входят. Требование про новый ресурс выполняется.",
  },
  {
    bucket: "accept",
    topic: "Подтверждение перед записью",
    tz: "В новом чате перед записью ассистент спрашивает подтверждение.",
    docs: "Фраза уже есть в тексте write_register_record. У записи destructiveHint, у остальных инструментов чтение. Код вызов не перехватывает.",
    resolution:
      "Принять. Подтверждение делает клиент по тексту инструмента и метке. Это и есть приёмка ТЗ, отдельный протокол не нужен.",
  },
  {
    bucket: "plan",
    topic: "Порядок истории в плане",
    tz: "ТЗ порядок не задаёт. Расхождение между спецификацией и планом.",
    docs: "Спецификация: период по убыванию, затем измерения. Задача 2 собирает запрос в ЗаписиРегистра только с Период УБЫВ. Задача 3 пишет «затем измерения», но модуль данных уже не меняет.",
    resolution:
      "До кода дописать вторичную сортировку в интерфейс ЗаписиРегистра задачи 2. Иначе задаче 3 некуда её вставить.",
  },
  {
    bucket: "plan",
    topic: "Поля описания в задаче 1",
    tz: "Описание: измерения, ресурсы, реквизиты, типы, периодичность.",
    docs: "Спецификация добавляет periodicity, exchange (шаблон записи, правила периода и отбора) и rules. Шаг 3 задачи 1 перечисляет обход полей и writable=false у реквизита. Интерфейс обещает весь ответ, чеклист — нет.",
    resolution:
      "Контракт ответа — JSON спецификации. В шаг 3 дописать periodicity, exchange и rules, чтобы исполнитель их не пропустил.",
  },
];

const ALIGNED: [string, string][] = [
  [
    "Маршруты",
    "GET /types, GET /register, GET /register/slice, GET /register/history, POST /register/record",
  ],
  [
    "Стартовое состояние",
    "Шаблоны регистров отвечают 501, четыре инструмента объявлены и ходят в заглушку, registers.http уже есть",
  ],
  [
    "Кто поддерживается",
    "Только независимые регистры сведений; подчинённый регистратору отклоняется понятной ошибкой",
  ],
  [
    "Запись",
    "Период клиента приводится к периодичности регистра; тот же период и ключ заменяют прежнее значение",
  ],
  [
    "Обмен",
    "Строка, число, дата, булево, ссылка и перечисление — как у объектов; ошибка клиента отдельно от сбоя 1С",
  ],
  [
    "MCP",
    "По инструменту на маршрут регистра; у записи destructiveHint, остальные только читают",
  ],
  [
    "Секреты",
    "Адрес, пользователь и пароль из переменных окружения; в коде и в записи подключения их нет",
  ],
  [
    "Границы",
    "БСП 3.2.1, те же расширение и MCP-сервер, основная конфигурация не меняется; удаления записей нет",
  ],
  [
    "Приёмка",
    "Файл запросов, выгрузка .cfe, новый чат, подтверждение перед записью, новая цена видна в регистре цен",
  ],
];

const TONE: Record<Bucket, "danger" | "info" | "warning"> = {
  decide: "danger",
  accept: "info",
  plan: "warning",
};

export default function TzRegistersReview() {
  const theme = useHostTheme();
  const [filter, setFilter] = useCanvasState<Filter>("filter", "all");
  const rows = FINDINGS.filter((item) => filter === "all" || item.bucket === filter);
  const decide = FINDINGS.filter((item) => item.bucket === "decide").length;
  const accept = FINDINGS.filter((item) => item.bucket === "accept").length;
  const plan = FINDINGS.filter((item) => item.bucket === "plan").length;

  return (
    <Stack gap={20}>
      <Stack gap={8}>
        <H1>ТЗ регистров против спецификации и плана</H1>
        <Text tone="secondary">
          Маршруты, инструменты, запись с периода и приёмка совпадают. Одно место
          в сценарии ТЗ спецификация решает иначе, семь достроек контракта стоит
          принять, в плане до кода поправить два места.
        </Text>
      </Stack>

      <Row gap={16}>
        <Stat value={String(decide)} label="Решить по сценарию" tone="danger" />
        <Stat value={String(accept)} label="Принять как в спецификации" />
        <Stat value={String(plan)} label="Поправить план" tone="warning" />
      </Row>

      <Callout tone="warning" title="Слово «цена» в запрос не уходит">
        Синоним регистра — «Демо: Цены номенклатуры», имя — _ДемоЦеныНоменклатуры.
        Подстрока «цена» туда не входит и по выгрузке находит справочник сценариев
        обмена. Подстрока «цен» находит регистр цен первым. Так уже записаны
        спецификация, план и registers.http. Поиск в 1С остаётся общим с
        справочниками и документами.
      </Callout>

      <Stack gap={8}>
        <H2>Как закрыть расхождения</H2>
        <Row gap={8} wrap>
          {(
            [
              ["all", `Все ${FINDINGS.length}`],
              ["decide", `Решить ${decide}`],
              ["accept", `Принять ${accept}`],
              ["plan", `План ${plan}`],
            ] as [Filter, string][]
          ).map(([id, label]) => (
            <Pill key={id} active={filter === id} onClick={() => setFilter(id)}>
              {label}
            </Pill>
          ))}
        </Row>
        <Table
          headers={["Тема", "ТЗ", "Спецификация и план", "Как разрешить"]}
          columnAlign={["left", "left", "left", "left"]}
          rowTone={rows.map((item) => TONE[item.bucket])}
          striped
          rows={rows.map((item) => [
            <Text key="topic" weight="semibold" size="small">
              {item.topic}
            </Text>,
            <Text key="tz" size="small">
              {item.tz}
            </Text>,
            <Text key="docs" size="small">
              {item.docs}
            </Text>,
            <Text key="resolution" size="small">
              {item.resolution}
            </Text>,
          ])}
        />
        <Text size="small" tone="tertiary">
          Источники: ТЗ регистров, docs/superpowers/specs/2026-10-29-registers-design.md,
          docs/superpowers/plans/2026-10-29-registers.md, каркас onec-objects и выгрузка
          метаданных БСП 3.2.1. Сверка 1 ноября 2026.
        </Text>
      </Stack>

      <Stack gap={8}>
        <H2>Где документы уже сходятся</H2>
        <Text tone="secondary" size="small">
          Эти пункты ТЗ спецификация и план передают без развилки. Менять их не нужно.
        </Text>
        <Table
          headers={["Требование ТЗ", "Как передано"]}
          rows={ALIGNED}
          striped
        />
      </Stack>

      <Text size="small" tone="tertiary" style={{ color: theme.text.tertiary }}>
        Точка в строке статистики — тон вывода: красный ждёт подтверждения, жёлтый
        правка плана до реализации.
      </Text>
    </Stack>
  );
}

